use semio_framework_test_fixtures::fixture_text;
#[path="../../../../♻️retirement/🧪️tests/⏱️work/🦀️.rs"]mod close_work_policy;
use crate::retained_clone::retained_clone_grant_admits;
use super::*;
use crate::{DslValue,Number,ValueRefusalKind,list::persistent::PersistentList,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement},shared_issuance::SealedShared};
#[derive(crate::RetireOwned,crate::NativeReceive)]#[value(crate="crate",native_owned="crate")]
struct Row{label:SealedShared<String>,rank:i64}
impl Clone for Row{fn clone(&self)->Self{panic!("persistent native receiving must never clone an owned typed row")}}


use crate::source_fixture::{Wallet,receive};
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(run)}
fn fixture()->serde_json::Value{serde_json::from_str(fixture_text!("../../📋️list/🧪️tests/🧫️fixtures/📐️.json")).unwrap()}
fn account(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),total:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));total.0+=h.0;total.1+=h.1;}
fn denied(g:RetainedCloneGrant,d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn input(count:usize,prefix:&str,stride:i64,repeat:usize,bad:Option<usize>)->DslValue{DslValue::Array((0..count).map(|i|DslValue::Object(vec![("label".into(),DslValue::String(if i==0{prefix.repeat(repeat)}else{format!("{prefix}{i}")})),("rank".into(),if bad==Some(i){DslValue::String("refused".into())}else{DslValue::Number(Number::Int(i as i64*stride))})])).collect())}
fn source<I:RetireOwned+Sync>(value:I,bank:&mut Wallet,total:&mut(usize,usize))->RetainedCloneSource<I>{let mut wallet=(bank,total);crate::source_fixture::capture(value,&mut wallet,|w|w.0.loan(1,4096),|w,p,work,heap,g|{account(p,g,heap,w.1);w.0.post(p,work,g,heap)})}
fn make_original(count:usize,prefix:&str,stride:i64,repeat:usize,bad:Option<usize>,bank:&mut Wallet,total:&mut(usize,usize))->RetainedCloneSource<DslValue>{let(value,h)=observe(||input(count,prefix,stride,repeat,bad));total.0+=h.0;total.1+=h.1;source(value,bank,total)}
fn post<E:std::fmt::Debug>(bank:&mut Wallet,turn:crate::RetainedWorkOutcome<RetainedCloneStep,E>,g:RetainedCloneGrant,heap:(usize,usize),total:&mut(usize,usize),receipt:impl FnOnce(&E)->RetainedCloneProgress)->Result<RetainedCloneStep,E>{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(receipt);account(p,g,heap,total);bank.post(p,turn.work,g,heap);turn.result}
fn close<T:RetireOwned>(value:T,bank:&mut Wallet,total:&mut(usize,usize)){let(mut owner,h)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("persistent fixture retirement")));assert_eq!(h,(0,0));let mut work=close_work_policy::Work::new();while !owner.terminal_is_empty(){let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=bank.loan(1,4096);let(result,h)=observe(||owner.step(g));let actual=owner.last_turn_work();let s=post(bank,crate::RetainedWorkOutcome{result,work:actual},g,h,total,ValueError::retained_progress).unwrap();work.observe(s.progress()==Default::default()&&!owner.terminal_is_empty()&&owner.next_demand(4096).unwrap()==d);}assert_eq!(observe(||drop(owner)).1,(0,0));}
fn close_receiver<I:NativeListSource+?Sized>(receiver:&mut NativePersistentListReceiver<I,Row>,rows:usize,bank:&mut Wallet,total:&mut(usize,usize))where Row:NativeReceive<I::Row>{receiver.begin_close();let mut work=close_work_policy::Work::for_rows(rows);while !receiver.terminal_is_empty(){let d=receiver.close_demands(4096).unwrap();assert!(d.copy_bytes<=4096,"selected close quote exceeds its authored body");let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||receiver.close_step(denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));}let(turn,h)=observe(||receiver.close_step(g));let s=post(bank,turn,g,h,total,ValueError::retained_progress).unwrap();work.observe(s.progress()==Default::default()&&!receiver.terminal_is_empty()&&receiver.close_demands(4096).unwrap()==d);}}
fn take<I:NativeListSource+?Sized>(receiver:&mut NativePersistentListReceiver<I,Row>,g:RetainedCloneGrant,bank:&mut Wallet,total:&mut(usize,usize))->PersistentList<Row>where Row:NativeReceive<I::Row>{let(turn,h)=observe(||receiver.take(g));let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();account(p,g,h,total);bank.post(p,turn.work,g,h);turn.result.unwrap().unwrap().0}
#[test]fn native_persistent_list_receives_original_rows_and_preserves_all_cancelled_custody(){
 let f=fixture();let prefix=f["prefix"].as_str().unwrap();let stride=f["stride"].as_i64().unwrap();let repeat=f["firstRepeat"].as_u64().unwrap()as usize;
 for count in f["cases"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;for cut in std::iter::once(None).chain(f["cuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(count,prefix,stride,repeat,None,&mut bank,&mut total);let foreign=make_original(count,prefix,stride,repeat,None,&mut bank,&mut total);let pointer=std::ptr::from_ref(original.borrow().get());let expected=serde_json::Value::from(original.borrow().get());let(mut receiver,h)=observe(<PersistentList<Row>as NativeReceive<DslValue>>::receiver);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut turns=0;let mut prepared=0;let mut output=None;let mut work=close_work_policy::Work::for_rows(count);
  while !receiver.output_ready()&&cut.is_none_or(|cut|turns<cut){let d=receiver.demands(original.borrow(),512).unwrap();if turns>0{assert!(receiver.demands(foreign.borrow(),512).is_err())}let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||receive(&mut control,denied,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,512,denied)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(original.borrow(),512).unwrap(),d);}let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,512,g)));let s=post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();prepared+=h.0;assert_eq!(control.owned_bytes(),prepared);assert_eq!(std::ptr::from_ref(original.borrow().get()),pointer);turns+=1;work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d);}
  if cut.is_none(){let d=receiver.take_demand().unwrap();let g=bank.loan(1,4096);for denied in denied(g,d){let(turn,h)=observe(||receiver.take(denied));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(h,(0,0));}let root=take(&mut receiver,g,&mut bank,&mut total);assert_eq!(root.len(),count);let actual:Vec<_>=(0..count).map(|i|{let row=root.get(i).unwrap();serde_json::json!({"label":row.label.as_str(),"rank":row.rank})}).collect();assert_eq!(serde_json::Value::Array(actual),expected);output=Some(root);}
  close_receiver(&mut receiver,count,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(foreign,&mut bank,&mut total);close(original,&mut bank,&mut total);if let Some(root)=output{for i in 0..count{assert_eq!(root.get(i).unwrap().rank,i as i64*stride);}close(root,&mut bank,&mut total);}assert_eq!(total.0,total.1);
 }}
}
#[test]fn native_persistent_list_later_row_refusal_retains_original_partial_owner(){let f=fixture();for bad in f["invalidRows"].as_array().unwrap(){let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(257,"α🙂",2,1,Some(bad.as_u64().unwrap()as usize),&mut bank,&mut total);let before=serde_json::Value::from(original.borrow().get());let mut receiver=<PersistentList<Row>as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut refused=false;let mut work=close_work_policy::Work::for_rows(257);while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512).unwrap();let g=bank.loan(1,4096);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,512,g)));match post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress){Ok(s)=>work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d),Err(error)=>{assert_eq!(error.primary.as_ref().unwrap().kind,ValueRefusalKind::InvalidValue);refused=true;break}}}assert!(refused);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,257,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);assert_eq!(total.0,total.1);}}
#[test]fn native_persistent_list_original_callback_refusal_preserves_partial_receiving(){let f=fixture();for allow in[0usize,1,3,8,31,256]{let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(17,"α🙂",2,10923,None,&mut bank,&mut total);let before=serde_json::Value::from(original.borrow().get());let mut receiver=<PersistentList<Row>as NativeReceive<DslValue>>::receiver();let calls=std::cell::Cell::new(0);let mut callback=|_|{let n=calls.get();calls.set(n+1);n<allow};let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut stopped=false;let mut work=close_work_policy::Work::for_rows(17);while !receiver.output_ready(){let d=receiver.demands(original.borrow(),512).unwrap();let g=bank.loan(1,4096);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,512,g)));match post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress){Ok(s)=>work.observe(s.progress()==Default::default()&&!receiver.output_ready()&&receiver.demands(original.borrow(),512).unwrap()==d),Err(error)=>{assert_eq!(error.primary.as_ref().unwrap().kind,ValueRefusalKind::Canceled);stopped=true;break}}}assert!(stopped);assert_eq!(serde_json::Value::from(original.borrow().get()),before);close_receiver(&mut receiver,17,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);assert_eq!(total.0,total.1);}}
#[test]fn native_persistent_list_receiving_fits_original_interaction_quantum(){let f=fixture();for row in f["bodyReservations"].as_array().unwrap(){assert_eq!(super::receiving_child_body_budget(row["bodyBytes"].as_u64().unwrap()as usize,row["metadataBytes"].as_u64().unwrap()as usize),row["childBytes"].as_u64().unwrap()as usize);}let q=&f["interactionQuantum"];let copy=q["copyBytes"].as_u64().unwrap()as usize;let items=q["workItems"].as_u64().unwrap()as usize;let maximum=q["maximumTurns"].as_u64().unwrap()as usize;let mut bank=Wallet::from_profile(&f["stock"]);let mut total=(0,0);let original=make_original(17,"α🙂",2,10923,None,&mut bank,&mut total);let mut receiver=<PersistentList<Row>as NativeReceive<DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut turns=0;let mut born=0;let mut saw_control_batch=false;let mut phases=[0usize;16];assert_eq!(f["controlBatch"]["maximumChildPosts"],1);assert_eq!(f["controlBatch"]["independentWork"],true);assert_eq!(f["controlBatch"]["recordControlBatch"],true);assert_eq!(f["controlBatch"]["sharedControlBatch"],true);assert_eq!(f["controlBatch"]["custodyBatch"],true);while !receiver.output_ready(){phases[receiver.phase as usize]+=1;let d=receiver.demands(original.borrow(),copy).unwrap();assert!(d.copy_bytes<=copy,"original persistent quote exceeds responsive quantum");let g=bank.loan(items,copy);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(f["interactionQuantum"]["workUnits"].as_u64().unwrap()),|control|receiver.advance(original.borrow(),control,copy,g)));assert!(turn.work<=items as u64);saw_control_batch|=turn.work>1;post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();born+=h.0;assert_eq!(control.owned_bytes(),born);turns+=1;assert!(turns<=maximum,"original wide persistent receiving exceeded authored throughput bound: row={}/{} phase={} child={:?} phaseTurns={:?}",receiver.index,receiver.count,receiver.phase as u8,receiver.child.get().map(|c|(c.phase,c.field,c.stage)),phases);}assert!(saw_control_batch,"actual large physical offer permits multiple genuine control effects with independent observed CPU");let root=take(&mut receiver,bank.loan(items,copy),&mut bank,&mut total);assert_eq!(root.len(),17);assert_eq!(root.get(0).unwrap().label.as_str(),"α🙂".repeat(10923));close_receiver(&mut receiver,17,&mut bank,&mut total);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);close(root,&mut bank,&mut total);assert_eq!(total.0,total.1);}
#[test]fn native_persistent_list_child_custody_prices_stable_birth_and_cancelled_release(){type Input=Vec<DslValue>;type Child=<Row as NativeReceive<DslValue>>::Receiver;let f=fixture();assert_eq!(f["childCustody"]["storage"],"stable-owned-allocation");for row in f["childCustody"]["rows"].as_array().unwrap(){let child=row["childBytes"].as_u64().unwrap();assert_eq!(row["copyBytes"],0);assert_eq!(row["capacityBytes"],if row["event"]=="birth"{child}else{0});assert_eq!(row["releaseBytes"],if row["event"]=="terminal-release"{child}else{0});}let copy=f["interactionQuantum"]["copyBytes"].as_u64().unwrap()as usize;let mut bank=Wallet::from_profile(&f["stock"]);let(rows,seed)=observe(||{let DslValue::Array(rows)=input(1,"α🙂",2,1,None)else{unreachable!()};rows});let mut total=seed;let original=source(rows,&mut bank,&mut total);let pointer=std::ptr::from_ref(original.borrow().get());let mut receiver=<PersistentList<Row>as NativeReceive<Input>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<30,&mut callback);let mut work=close_work_policy::Work::for_rows(1);while !(receiver.phase==Phase::RowBirth&&!receiver.child.reserved()){let d=receiver.demands(original.borrow(),copy).unwrap();let g=bank.loan(1,copy);let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,copy,g)));let s=post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();work.observe(s.progress()==Default::default()&&receiver.demands(original.borrow(),copy).unwrap()==d);}let d=receiver.demands(original.borrow(),copy).unwrap();let allocation=std::mem::size_of::<Child>();assert_eq!(d.copy_bytes,0);assert_eq!(d.capacity_bytes,allocation);assert_eq!(d.depth,1);let g=bank.loan(1,copy);for denied in denied(g,d){let(turn,h)=observe(||receiver.advance(original.borrow(),&mut control,copy,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(original.borrow(),copy).unwrap(),d);assert_eq!(std::ptr::from_ref(original.borrow().get()),pointer);}let(turn,h)=observe(||receive(&mut control,g,bank.work_loan(1),|control|receiver.advance(original.borrow(),control,copy,g)));post(&mut bank,turn,g,h,&mut total,crate::OriginalReceivingPrimary::retained_progress).unwrap();assert_eq!(h.0,allocation);let address=receiver.child.address();assert!(address.is_some());assert!(!receiver.child.initialized());let next=receiver.demands(original.borrow(),copy).unwrap();assert_eq!(next.copy_bytes,0);assert_eq!(next.capacity_bytes,0);assert_eq!(receiver.child.address(),address);receiver.begin_close();let mut work=close_work_policy::Work::for_rows(1);let mut released=false;while !receiver.terminal_is_empty(){let d=receiver.close_demands(copy).unwrap();let g=bank.loan(1,copy);let(turn,h)=observe(||receiver.close_step(g));let s=post(&mut bank,turn,g,h,&mut total,ValueError::retained_progress).unwrap();released|=allocation>0&&h.1==allocation;work.observe(s.progress()==Default::default()&&!receiver.terminal_is_empty()&&receiver.close_demands(copy).unwrap()==d);}assert!(allocation==0||released);assert_eq!(observe(||drop(receiver)).1,(0,0));close(original,&mut bank,&mut total);assert_eq!(total.0,total.1);}
